mapper.select:
SELECT p.id AS product_id, p.code AS product_code, p.name AS product_name, sp.id AS spec_id, sp.spec, COALESCE(u.unit, '') AS unit, COALESCE(sp.stock, 0) AS stock
LEFT JOIN inv_product_units u ON u.spec_id = sp.id AND u.is_base AND u.deleted_at IS NULL
ORDER BY p.id, sp.sort, sp.id LIMIT #{limit} OFFSET #{offset}
